{"code":"import pandas as pd, statsmodels.api as sm
D=pd.read_csv('data/explore.csv').dropna(subset=['recovery_score']); xs=['vitamin_d','sleep_hours','steps_k','bmi','crp_level','dose_mg','age_decades','sodium_mmol','hdl','stress_index']
for x in xs:
 z=pd.concat([D[[x]],pd.get_dummies(D.hospital,drop_first=True,dtype=float)],axis=1)
 m=sm.OLS(D.recovery_score,sm.add_constant(z),missing='drop').fit()
 print(x,round(m.params[x],3),round(m.pvalues[x],5))"}
